    private static SVGPath path(String content, boolean evenOdd) {
        SVGPath svgPath = new SVGPath();
        svgPath.setContent(content);
        if (evenOdd) svgPath.setFillRule(FillRule.EVEN_ODD);
        svgPath.getStyleClass().add("icon");
        return svgPath;
    }
